import styled from 'styled-components';




export const ChatContainer = styled.div`
    
flex: 2;
border-left: 1px solid #17252A;
border-right: 1px solid #17252A;
max-height: 100%;
display: flex;


flex-direction: column;


.iconsContainer{
    display: flex;
    align-items: center;
    gap: 10px;
}
.chatBtn svg{
    width: 25px;
    height: 25px;
}
.top{
    padding: 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background-color: ${p => p.theme.color.white};
    border-bottom: 1px solid #17252A;
}
.user{
    display: flex;
    align-items: center;
    gap: 10px;
}
.text{
    display: flex;
    flex-direction: column;
    gap: 5px;
}
span{
    font-size: 14px;
    font-weight: 300;
    color: ${p => p.theme.color.fontColor};
    font-family: ${p => p.theme.fontFamily};
}

p{
    font-size: 12px;
    font-weight: 300;
    color: ${p => p.theme.color.fontColor_Grеy};
    font-family: ${p => p.theme.fontFamily};
}
.center{
    flex: 1;
    padding: 20px;
    display: flex;
    max-height: calc(100vh - 13%);
    flex-direction: column;
    overflow: auto;
    gap: 20px;

    .message{
        max-width: 70%;
        display: flex;
        gap: 20px;
        align-items: center;
        padding: 10px;
        border-radius: 20px;
        
        background-color: #E0F7FA; 
        position: relative;
        
        
        

        &.own{
            align-self: flex-end;
                    padding: 10px;
                    border-radius: 20px;
                    background-color: #FFF3E0 ;
            .texts{
                p{  
                    color: #004D40;
                }
            }
        }
    }
  
    
  &::-webkit-scrollbar {
    width: 5px; 
  }

  &::-webkit-scrollbar-track {
    background: #f1f1f1; 
  }

  &::-webkit-scrollbar-thumb {
    background: #888; 
    border-radius: 10px; 
  }

  &::-webkit-scrollbar-thumb:hover {
    background: #555; 
  }

}
.bottom{
    padding: 20px;
    display: flex;
    align-items: center;
    justify-content: space-between; 
    gap: 20px;
    border-top: 1px solid ${p => p.theme.color.grey};
    background-color: ${p => p.theme.color.white};

    .emojiContainer svg {
    width: 25px;
    height: 25px;
    }

    .icons{
        display: flex;
        align-items: center;
        gap: 20px;
    }
    .icons svg{
        width: 25px;
        height: 25px;
    }

    input {
        flex: 1;
        background-color: ${p => p.theme.color.grey};
        opacity: 0.5;
        border: none;
        outline: none;
        color: black;

        padding: 10px;
        border-radius: ${p => p.theme.border.radius20px};
        transition: opacity 0.3s ease;

    }
    input:hover{
        opacity: 1;
    }
    .btnMicro svg{
        width: 25px;
        height: 25px;
        fill: ${p => p.theme.color.darkGrey}

    }
    .btnMicro{
        padding: 5px 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 100%;
        padding: 10px;
        transition: background-color 0.5s ease;
    }
    .btnMicro:hover {
        background-color: rgba(128, 128, 128, 0.5); 
       
        animation: pulse 1s infinite;
        

    }
    

    @keyframes pulse {
    0% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.2);
    }
    100% {
        transform: scale(1);
    }
}
    .sendButton{
        display: flex;
        align-items: center;
        justify-content: center;

        background-color: ${p => p.theme.color.sendbtnColor};
        padding: 10px;
        border-radius: ${p => p.theme.border.radius_cricle};
        transition: opacity 1s ease;

    }
    .sendButton svg{
        fill: ${p => p.theme.color.white};
    }
   

    .sendButton:hover{
        opacity: 0.8;
        
    }
    .imgIconBtn{
        padding: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 100%;
        
        transition: background-color 0.5s ease;

    }
    .imgIconBtn svg{
        fill: ${p => p.theme.color.darkGrey}
    }

    .imgIconBtn:hover{
        background-color: rgba(128, 128, 128, 0.5); 
       
       animation: pulse 1s infinite;
    }

    .emojiBtn{
        padding: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 100%;
        transition: background-color 0.5s ease;
    }
    .emojiBtn svg{
        fill: ${p => p.theme.color.darkGrey}
    }
    .emojiBtn:hover{
        background-color: rgba(128, 128, 128, 0.5); 
       
       animation: pulse 1s infinite;
    }
    .emojiContainer{
        position: relative;

        .emojipicker{
            position: absolute;
            bottom: 50px;
            left: 0;

        }

    }
    

}

`