import styled from 'styled-components';


export const SearchBarContainer = styled.div`
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 20px;
    background-color: ${p => p.theme.color.white};


    .searchBar{
        flex: 1;
        /* cursor: pointer; */
        background-color: ${p => p.theme.color.searchColor};
        border-radius: ${p => p.theme.border.radius200px};
        display: flex;
        padding: 10px;

        input{
        flex: 1;
        background: transparent;
        border: none;
        outline: none;
        color: ${p => p.theme.color.white};
    }
    }
    .searchBar svg{
        fill: ${p => p.theme.color.btnColor};
        stroke: ${p => p.theme.color.btnColor};
        width: 30px;
        height: 30px;
    }
    button{
        display: flex;
        padding: 5px;
        align-items: center;
        background-color: rgba(128, 128, 128, 0.5);
        border-radius: ${p => p.theme.border.radius10px};
    }
    button svg {
    stroke: ${p => p.theme.color.btnColor};
    fill: ${p => p.theme.color.btnColor};
    width: 30px;
    height: 30px;
    transition: transform 1s ease, opacity 1s ease;
}

button:hover svg {
    animation: pulse 1s infinite alternate; /* Применение анимации */
}

@keyframes pulse {
    0% {
        transform: scale(1);
        opacity: 1;
    }
    100% {
        transform: scale(1.1);
        opacity: 0.8;
    }
}

`