import styled from 'styled-components';

export const ChatlistContainer = styled.div`
/* flex: 1; */
display: flex;
flex-direction: column;
height: 84dvh;
overflow: auto;
/* overflow: hidden; */
/* max-height: 700px; */

  &::-webkit-scrollbar {
    width: 5px; 
  }

  &::-webkit-scrollbar-track {
    background: #f1f1f1; 
  }

  &::-webkit-scrollbar-thumb {
    background: #888; 
    border-radius: 10px; 
  }

  &::-webkit-scrollbar-thumb:hover {
    background: #555; 
  }


.chat-list {
  /* width: 100%;
  height: 50px; */
  padding: 10px;
  background-color: #FFFFFF;
  border-bottom: 1px solid rgba(0, 0, 0, 0.1);
  transition: background-color 0.3s ease; 
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative; 
  /* border-radius: 5px; */
  /* overflow: hidden; */
  cursor: pointer;
}

.chat-list-content {
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 1;
}

.chat-list-background {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(255, 255, 180, 0.5);
  filter: brightness(1.2) contrast(1);
  z-index: 0;
  transition: opacity 0.3s ease;
  opacity: 0;
  pointer-events: none; 
}

.chat-list:hover .chat-list-background  {
  opacity: 1; 
}

.chat-list:hover .chat-message:hover{
  cursor: pointer;
  color: rgba(0, 0, 0, 0.9);
}

.chat-message{
    color: rgba(0, 0, 0, 0.6);
}

`
