import styled from 'styled-components';


export const UserinfoContainer = styled.div`
display: flex;
/* justify-content: center;  */
align-items: center;
background-color: ${p => p.theme.color.headColor};

padding: 10px 10px 10px 10px;
border-radius: ${p => p.theme.border.radius10px};
border: 1px solid #17252A;

.userName{
    font-size: 30px;
    
}
.user{
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 30px;
}
.userAvatar{
   
    /* border: 1px solid #000000; */
    border-radius: 50%;

}
.icons{
    display: flex;
    gap: 5px;
    align-items: center;
    transform: scale(1.1);
    
}
.icons button {
    background: 0;
    border: 0;
    padding: 0;
    display: flex;
    justify-content: center;
    align-items: center;


}
.icons:hover{
    cursor: pointer;
   
}
.icons svg {
    fill: ${p => p.theme.color.iconColor};
    stroke: ${p => p.theme.color.iconColor};
    transition-duration: 0.5s, 0.2s; /* Длительность для каждого свойства */
    transition-timing-function: ease-in-out;
    
}
.icons svg:hover{
    transform: scale(1.1);
    fill: #000;
}
`

