import { Avatar } from "@mui/material";

export const ChatListItem = ({ chat, id, name }) => {
  const handleMessage = () => {
    console.log("Open chat", {name}, { chat }, { id });
  };

  return (
    <>
      <div className="chat-list" onClick={handleMessage}>
        <div className="chat-list-background"></div>
        <div className="chat-list-content">
          <div className="avatar-container">
            <Avatar
              className="chatAvatar"
              alt={name}
              src="/static/images/avatar/1.jpg"
            />
            
          </div>

          <div className="name">
              <span>{name}</span>
              <p className="chat-message">{chat}</p>
            </div>
          
          
        </div>
      </div>
    </>
  );
};
