import { ReactComponent as SearchBaricon } from '../../../../images/icon/SearchBaricon.svg';
import {ReactComponent as PlusIcon } from '../../../../images/icon/PlusIcon.svg';
import { ReactComponent as MinusIcon} from '../../../../images/icon/MinusIcons.svg'
import {SearchBarContainer} from './SearchBar.style';
import { useState } from 'react';


export const SearchBar = () => {
    const [addMode, setAddMode] = useState(true)
    // console.log(addMode);

    return (
        <>
        <SearchBarContainer className='search'>
            <div className="searchBar">
                    <SearchBaricon/>
                    <input type="text" placeholder='Search' />
            </div>
            <button type='button' onClick={() => setAddMode((prev) => !prev)}>{addMode ? <PlusIcon/> : <MinusIcon/> }</button>
            

        </SearchBarContainer>
        </>
    )
}